package com.example.academic;

import static org.junit.jupiter.api.Assertions.*;
import com.example.academic.admission.Program;
import com.example.academic.branch.*;
import com.example.academic.course.*;
import com.example.academic.lead.*;
import com.example.academic.security.*;
import com.example.academic.website.*;
import com.example.academic.common.*;
import jakarta.persistence.EntityManager;
import java.math.BigDecimal;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.transaction.annotation.*;
import static com.example.academic.website.WebsitePublication.*;

@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:website-intake-tests;MODE=MySQL;DB_CLOSE_DELAY=-1","logging.level.org.hibernate.SQL=WARN"})
@Transactional(isolation=Isolation.READ_COMMITTED) @TestInstance(TestInstance.Lifecycle.PER_CLASS)
class WebsiteIntakeWorkflowTest {
  @Autowired JdbcTemplate jdbc;@Autowired EntityManager em;
  @Autowired WebsiteIntakeService service;@Autowired WebsiteCatalogService catalog;
  @Autowired WebsitePublicationRepository publications;@Autowired WebsiteInquiryRepository inquiries;
  @Autowired LeadRepository leads;@Autowired LeadActivityRepository events;
  @Autowired LeadService leadService;
  @Autowired WebsiteTeacherService teachers;
  @MockitoBean WebsiteIntakeLimiter limiter;
  Branch branch;Program program;Course course;
  @BeforeAll void authSchema(){
    jdbc.execute("create table if not exists accounts(id bigint primary key,username varchar(50),status boolean,role varchar(20))");
    jdbc.execute("create table if not exists account_branches(id bigint generated by default as identity primary key,account_id bigint,branch_id bigint,status boolean)");
    for(String table:List.of("staffs","admins"))jdbc.execute("create table if not exists "+table+"(account_id bigint primary key,full_name varchar(100),hire_date date,end_date date,work_status varchar(20))");
    jdbc.execute("create table if not exists teachers(id bigint primary key,account_id bigint,full_name varchar(100),specialization varchar(100),qualification varchar(100),hire_date date,end_date date,work_status varchar(20))");
  }
  void actor(){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new CurrentUser(1L,1L,null,Role.SUPER_ADMIN,"superadmin"),null,List.of()));}
  WebsitePublication publish(Kind kind,Long id,String slug,Long parent){return catalog.edit(kind,new WebsiteDto.Edit(id,0L,slug,State.PUBLISHED,"Nội dung đã duyệt",null,null,null,null,null,null,parent,false));}
  Branch branch(String code,String slug){var b=new Branch();b.setCode(code);b.setName(code);b.setAddress("Địa chỉ xác nhận");b.setPhone("0901234567");em.persist(b);publish(Kind.BRANCH,b.getId(),slug,null);return b;}
  @BeforeEach void setup(){
    actor();branch=branch("CN1","chi-nhanh-1");program=new Program();program.setCode("GE");program.setName("Tiếng Anh");em.persist(program);publish(Kind.PROGRAM,program.getId(),"tieng-anh",null);
    course=new Course();course.setCode("KH1");course.setName("Giao tiếp");course.setBranchId(branch.getId());course.setTuitionFee(new BigDecimal("3000000"));course.setMaxStudents(20);em.persist(course);publish(Kind.COURSE,course.getId(),"giao-tiep",program.getId());
    person(101L,"STAFF",branch.getId());person(102L,"STAFF",branch.getId());person(201L,"ADMIN",branch.getId());em.flush();SecurityContextHolder.clearContext();
  }
  void person(Long id,String role,Long branchId){jdbc.update("insert into accounts(id,username,status,role) values(?,?,true,?)",id,"user"+id,role);jdbc.update("insert into "+(role.equals("STAFF")?"staffs":"admins")+"(account_id,full_name,work_status) values(?,?,'ACTIVE')",id,"Nhân sự "+id);jdbc.update("insert into account_branches(account_id,branch_id,status) values(?,?,true)",id,branchId);}
  WebsiteIntakeDto.Request request(String key,String phone,String branchSlug,String name){return new WebsiteIntakeDto.Request(key,name,phone,null,branchSlug,"tieng-anh",branchSlug.equals("chi-nhanh-1")?"giao-tiep":null,null,"Tư vấn lịch buổi tối",true,"");}
  WebsiteIntakeDto.Request request(){return request(UUID.randomUUID().toString(),"0901234567","chi-nhanh-1","Nguyễn An");}
  @AfterEach void clear(){SecurityContextHolder.clearContext();}
  @Test void anonymousRequestCreatesAssignedLeadAndConsentWithoutAccountOrStudent(){var r=request();long accounts=jdbc.queryForObject("select count(*) from accounts",Long.class),students=jdbc.queryForObject("select count(*) from students",Long.class);var response=service.submit(r);var receipt=inquiries.findById(r.requestId()).orElseThrow();var lead=leads.findById(receipt.getLeadId()).orElseThrow();assertEquals(101L,lead.getAssignedTo());assertEquals("WEBSITE",lead.getSource());assertEquals(Lead.Status.NEW,lead.getStatus());assertEquals(course.getId(),lead.getInterestedCourse().getId());assertEquals(WebsiteIntakeService.CONSENT_VERSION,receipt.getConsentVersion());assertNotNull(receipt.getCreatedAt());assertEquals(0L,events.findByLeadIdOrderByIdDesc(lead.getId()).getFirst().getActorId());assertEquals(accounts,jdbc.queryForObject("select count(*) from accounts",Long.class));assertEquals(students,jdbc.queryForObject("select count(*) from students",Long.class));assertEquals(1,response.getClass().getRecordComponents().length);}
  @Test void replayDoesNotDuplicateLeadReceiptOrHistory(){var r=request();assertEquals(service.submit(r),service.submit(r));assertEquals(1,leads.count());assertEquals(1,inquiries.count());assertEquals(1,events.count());}
  @Test void websiteInquiryContinuesThroughStaffCareAndStudentConversion(){
    var r=request();service.submit(r);var receipt=inquiries.findById(r.requestId()).orElseThrow();var lead=leads.findById(receipt.getLeadId()).orElseThrow();
    SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new CurrentUser(101L,101L,branch.getId(),Role.STAFF,"staff",List.of(branch.getId())),null,List.of()));
    var cared=leadService.interact(lead.getId(),new LeadDto.Interaction(LeadDto.Channel.CALL,"Đã tư vấn và xác nhận nhu cầu",Lead.Status.CONSULTING,null,lead.getVersion()));
    var converted=leadService.convert(lead.getId(),cared.version());assertNotNull(converted.convertedStudent());assertEquals(branch.getId(),converted.convertedStudent().branchId());assertEquals(Lead.Status.CONVERTED,converted.status());
    assertEquals(converted.convertedStudent().id(),leadService.convert(lead.getId(),converted.version()).convertedStudent().id());
  }
  @Test void repeatPhoneIsNormalizedAndDoesNotOverwriteExistingProspect(){var first=request();service.submit(first);var receipt=inquiries.findById(first.requestId()).orElseThrow();var lead=leads.findById(receipt.getLeadId()).orElseThrow();lead.setStatus(Lead.Status.CONSULTING);em.flush();service.submit(request(UUID.randomUUID().toString(),"+84 901-234-567","chi-nhanh-1","Tên khác"));assertEquals(1,leads.count());assertEquals(2,inquiries.count());assertEquals("Nguyễn An",lead.getFullName());assertEquals(Lead.Status.CONSULTING,lead.getStatus());assertEquals(101L,lead.getAssignedTo());assertEquals("WEBSITE_INQUIRY",events.findByLeadIdOrderByIdDesc(lead.getId()).getFirst().getAction());}
  @Test void classChoiceIsLinkedOnNewLeadAndLaterInquiryDoesNotEraseIt(){
    actor();var room=new com.example.academic.room.Room();room.setBranchId(branch.getId());room.setCode("TNROOM");room.setName("Room");room.setCapacity(20);em.persist(room);
    var sc=new com.example.academic.schoolclass.SchoolClass();sc.setBranchId(branch.getId());sc.setCode("TNCLASS");sc.setName("Intake class");sc.setCourse(course);sc.setRoom(room);sc.setTeacherId(1L);sc.setTeacherName("Teacher");sc.setStartDate(java.time.LocalDate.now(BusinessTime.ZONE).plusDays(7));sc.setEndDate(java.time.LocalDate.now(BusinessTime.ZONE).plusMonths(1));sc.setMaxSize(20);em.persist(sc);em.flush();publish(Kind.CLASS,sc.getId(),"tn-class",null);SecurityContextHolder.clearContext();
    var r=request();service.submit(new WebsiteIntakeDto.Request(r.requestId(),r.fullName(),r.phone(),null,r.branchSlug(),r.programSlug(),r.courseSlug(),"tn-class",r.note(),true,""));
    var lead=leads.findAll().getFirst();assertEquals(sc.getId(),lead.getPreferredClass().getId());
    service.submit(request());assertEquals(sc.getId(),lead.getPreferredClass().getId());assertEquals(2,inquiries.count());
  }
  @Test void changedPayloadCannotReuseReceipt(){var r=request();service.submit(r);var e=assertThrows(ApiException.class,()->service.submit(request(r.requestId(),r.phone(),r.branchSlug(),"Tên khác")));assertEquals(409,e.getStatus().value());assertEquals(1,leads.count());}
  @Test void leastLoadedActiveStaffReceivesNextLead(){service.submit(request());service.submit(request(UUID.randomUUID().toString(),"0901234568","chi-nhanh-1","Học viên B"));var recipients=leads.findAll().stream().map(Lead::getAssignedTo).toList();assertTrue(recipients.containsAll(List.of(101L,102L)));}
  @Test void inactiveStaffFallsBackToAssignedAdmin(){jdbc.update("update staffs set work_status='INACTIVE'");service.submit(request());assertEquals(201L,leads.findAll().getFirst().getAssignedTo());}
  @Test void noRecipientDoesNotClaimSuccess(){jdbc.update("update accounts set status=false");var e=assertThrows(ApiException.class,()->service.submit(request()));assertEquals(503,e.getStatus().value());assertEquals(0,leads.count());assertEquals(0,inquiries.count());}
  @Test void courseAndBranchMustMatch(){actor();var other=branch("CN2","chi-nhanh-2");person(103L,"STAFF",other.getId());SecurityContextHolder.clearContext();var r=request();var wrong=new WebsiteIntakeDto.Request(r.requestId(),r.fullName(),r.phone(),null,"chi-nhanh-2","tieng-anh","giao-tiep",null,null,true,"");assertThrows(ApiException.class,()->service.submit(wrong));assertEquals(0,leads.count());}
  @Test void requestsAtDifferentBranchesRemainSeparate(){service.submit(request());actor();var other=branch("CN2","chi-nhanh-2");person(103L,"STAFF",other.getId());SecurityContextHolder.clearContext();service.submit(request(UUID.randomUUID().toString(),"0901234567","chi-nhanh-2","Nguyễn An"));assertEquals(2,leads.count());assertEquals(Set.of(branch.getId(),other.getId()),new HashSet<>(leads.findAll().stream().map(Lead::getBranchId).toList()));}
  @Test void durablePhoneQuotaAndValidationAreEnforced(){for(int i=0;i<3;i++)service.submit(request());var e=assertThrows(ApiException.class,()->service.submit(request()));assertEquals(429,e.getStatus().value());assertEquals(3,inquiries.count());assertThrows(ApiException.class,()->WebsiteIntakeService.normalizePhone("hello"));assertThrows(ApiException.class,()->WebsiteIntakeService.normalizePhone("123"));}
  @Test void draftCourseCannotBeSubmitted(){var p=publications.findByKindAndSourceId(Kind.COURSE,course.getId()).orElseThrow();p.setState(State.DRAFT);em.flush();assertThrows(ApiException.class,()->service.submit(request()));assertEquals(0,leads.count());}
  @Test void publicTeachersNeedPublicationAndActiveMembership(){actor();jdbc.update("insert into accounts(id,username,status,role) values(301,'teacher',true,'TEACHER')");jdbc.update("insert into teachers(id,account_id,full_name,specialization,qualification,work_status) values(1,301,'Giáo viên An','GE','Thạc sĩ','ACTIVE')");jdbc.update("insert into account_branches(account_id,branch_id,status) values(301,?,true)",branch.getId());assertTrue(teachers.list(0,12,null).items().isEmpty());var p=teachers.edit(new WebsiteTeacherService.Edit(1L,0L,"giao-vien-an",State.PUBLISHED,"Nội dung được duyệt","Giao tiếp",null,false));assertNull(teachers.detail("giao-vien-an").qualification());teachers.edit(new WebsiteTeacherService.Edit(1L,p.getVersion(),"giao-vien-an",State.PUBLISHED,"Nội dung được duyệt","Giao tiếp",null,true));assertEquals("Thạc sĩ",teachers.detail("giao-vien-an").qualification());jdbc.update("update teachers set work_status='INACTIVE'");assertTrue(teachers.list(0,12,null).items().isEmpty());assertThrows(ApiException.class,()->teachers.detail("giao-vien-an"));assertFalse(Arrays.stream(WebsiteTeacherService.Profile.class.getRecordComponents()).anyMatch(c->List.of("accountId","phone","email","teacherId").contains(c.getName())));}
}
